import { ReactElement } from "react";

type SaleBadgeProps = {
    color: string;
    descount: number;
    icon: ReactElement;
    place: 'left' | 'right'
}

export const SaleBadge = ({color, descount, icon, place="left"}: SaleBadgeProps) => {
  return (

      <div className={color}>
        {place==='left' && icon}
          <span>{descount}</span>
          {place==='right' && icon}
      </div>

  )
}
